import type { Metadata } from "next";
import { Inter, Saira_Condensed } from "next/font/google";
import "./globals.css";
import { cn } from "@/lib/utils";
import { ThemeProvider } from "@/components/layout/theme-provider";
import { Toaster } from "sonner";
import { EmblemFlightProvider } from "./emblem-flight";

const inter = Inter({ subsets: ["latin"] });
const saira = Saira_Condensed({
  subsets: ["latin"],
  weight: ["500", "600", "700"],
  variable: "--font-saira",
});

export const metadata: Metadata = {
  title: "LSMS · Recrutement",
  description:
    "Los Santos Medical Services — rejoignez une equipe medicale structuree, reactive et disponible 24/7 sur Los Santos.",
  openGraph: {
    type: "website",
    title: "LSMS · Recrutement",
    description:
      "Los Santos Medical Services — rejoignez une equipe medicale structuree, reactive et disponible 24/7 sur Los Santos.",
  },
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html lang="fr" suppressHydrationWarning>
      <body className={cn("min-h-screen bg-background", inter.className, saira.variable)}>
        <ThemeProvider
          attribute="class"
          defaultTheme="dark"
          disableTransitionOnChange
        >
          <EmblemFlightProvider>{children}</EmblemFlightProvider>
          <Toaster />
        </ThemeProvider>
      </body>
    </html>
  );
}

import { redirect } from "next/navigation";

/** Page d'accueil LSMS — l'intro cinematique joue en premier. */
export default function Home() {
  redirect("/intro");
}

"use client";

import Image from "next/image";
import Link from "next/link";
import { useEffect, useRef, useState } from "react";

const NAV = [
  { href: "/accueil", label: "Accueil" },
  { href: "/accueil#services", label: "Services" },
  { href: "/accueil#faq", label: "FAQ" },
];

/**
 * Header LSMS — pilule verre sticky.
 * Desktop : nav complete inline. Mobile (<640px) : burger -> panneau verre
 * deroulant ; embleme + Postuler restent visibles.
 */
export function LsmsHeader() {
  const [open, setOpen] = useState(false);
  const headerRef = useRef<HTMLElement>(null);

  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => { if (e.key === "Escape") setOpen(false); };
    const onClick = (e: MouseEvent) => {
      if (headerRef.current && !headerRef.current.contains(e.target as Node)) setOpen(false);
    };
    window.addEventListener("keydown", onKey);
    window.addEventListener("click", onClick);
    return () => {
      window.removeEventListener("keydown", onKey);
      window.removeEventListener("click", onClick);
    };
  }, [open]);

  return (
    <header
      ref={headerRef}
      className="lsms-glass sticky top-[14px] z-50 mx-auto flex w-[calc(100%-24px)] max-w-[1180px] items-center justify-between gap-3 rounded-full px-4 py-[10px] sm:px-[26px]"
    >
      <Link href="/accueil" className="flex min-w-0 items-center gap-2.5 sm:gap-3">
        <Image
          src="/lsms/emblem.png"
          alt="Embleme LSMS"
          width={36}
          height={36}
          className="h-auto w-9 flex-none drop-shadow-[0_2px_10px_rgba(0,0,0,0.6)]"
        />
        <span
          className="truncate text-[15px] font-semibold tracking-[0.12em] text-[#F2F7F6]"
          style={{ fontFamily: "var(--font-barlow), sans-serif" }}
        >
          LOS SANTOS MEDICAL SERVICES
        </span>
      </Link>

      {/* Nav desktop (>=640px) */}
      <nav className="hidden items-center gap-0.5 sm:flex" aria-label="Navigation principale">
        {NAV.map((item) => (
          <Link
            key={item.label}
            href={item.href}
            className="rounded-full px-[18px] py-[10px] text-[13.5px] text-[rgba(235,245,242,0.75)] transition-colors duration-300 hover:bg-white/10 hover:text-white max-sm:flex max-sm:min-h-[44px] max-sm:items-center"
          >
            {item.label}
          </Link>
        ))}
        <Link
          href="/candidature"
          className="lsms-cta ml-2 !px-[26px] !py-[12px] !text-[13.5px]"
        >
          Postuler
        </Link>
      </nav>

      {/* Mobile (<640px) : burger + Postuler compact */}
      <div className="flex items-center gap-2 sm:hidden">
        <Link
          href="/candidature"
          className="lsms-cta flex min-h-[44px] items-center !px-[18px] !text-[12.5px]"
        >
          Postuler
        </Link>
        <button
          type="button"
          onClick={() => setOpen((v) => !v)}
          aria-expanded={open}
          aria-controls="lsms-mobile-nav"
          aria-label={open ? "Fermer le menu" : "Ouvrir le menu"}
          className="lsms-pill flex h-11 w-11 flex-none cursor-pointer items-center justify-center !p-0"
        >
          <svg width="18" height="18" viewBox="0 0 18 18" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" aria-hidden="true">
            <line x1="2" y1="4.5" x2="16" y2="4.5" style={{ transform: open ? 'translateY(4.5px) rotate(45deg)' : 'none', transition: 'transform 200ms var(--ease-out)', transformOrigin: 'center' }} />
            <line x1="2" y1="9" x2="16" y2="9" style={{ opacity: open ? 0 : 1, transition: 'opacity 150ms ease' }} />
            <line x1="2" y1="13.5" x2="16" y2="13.5" style={{ transform: open ? 'translateY(-4.5px) rotate(-45deg)' : 'none', transition: 'transform 200ms var(--ease-out)', transformOrigin: 'center' }} />
          </svg>
        </button>
      </div>

      {/* Panneau mobile : deroule SOUS la pilule */}
      <div
        id="lsms-mobile-nav"
        className="absolute left-0 right-0 top-[calc(100%+10px)] grid overflow-hidden rounded-[26px] sm:hidden"
        style={{
          gridTemplateRows: open ? "1fr" : "0fr",
          opacity: open ? 1 : 0,
          transition: "grid-template-rows 0.3s var(--ease-out), opacity 0.25s ease",
        }}
        aria-hidden={!open}
      >
        <div className="min-h-0 overflow-hidden">
          <nav
            className="lsms-glass flex flex-col gap-1 rounded-[26px] p-3"
            aria-label="Navigation mobile"
          >
            {NAV.map((item) => (
              <Link
                key={item.label}
                href={item.href}
                onClick={() => setOpen(false)}
                tabIndex={open ? 0 : -1}
                className="rounded-2xl px-5 py-3.5 text-[15px] text-[rgba(235,245,242,0.85)] transition-colors duration-200 hover:bg-white/10 hover:text-white"
              >
                {item.label}
              </Link>
            ))}
          </nav>
        </div>
      </div>
    </header>
  );
}

export function LsmsFooter() {
  return (
    <footer className="relative z-[1] flex flex-wrap items-center justify-between gap-6 border-t border-white/[0.08] bg-[rgba(3,7,8,0.8)] px-6 py-[38px] sm:px-11">
      <div className="flex items-center gap-3.5">
        <Image
          src="/lsms/emblem.png"
          alt=""
          width={28}
          height={28}
          className="h-auto w-7 opacity-75"
        />
        <span className="text-[13px] text-[#7C948E]">
          Los Santos Medical Services · Univers roleplay fictif
        </span>
      </div>
      <div className="flex flex-wrap gap-[22px] text-[13px] uppercase tracking-[0.1em]">
        <Link href="/accueil" className="text-[#8AA39C] hover:text-[var(--lsms-teal-light)]">
          Accueil
        </Link>
        <Link href="/candidature" className="text-[#8AA39C] hover:text-[var(--lsms-teal-light)]">
          Candidature
        </Link>
      </div>
    </footer>
  );
}

import type { Metadata } from "next";
import { Barlow_Condensed, Caveat, Inter, Saira_Condensed, Special_Elite } from "next/font/google";

const inter = Inter({ subsets: ["latin"], variable: "--font-inter" });
const saira = Saira_Condensed({
  subsets: ["latin"],
  weight: ["500", "600", "700"],
  variable: "--font-saira",
});
const barlow = Barlow_Condensed({
  subsets: ["latin"],
  weight: ["500", "600", "700"],
  variable: "--font-barlow",
});
const specialElite = Special_Elite({
  subsets: ["latin"],
  weight: "400",
  variable: "--font-typer",
});
const caveat = Caveat({
  subsets: ["latin"],
  weight: ["400", "500", "600"],
  variable: "--font-signature",
});

export const metadata: Metadata = {
  title: "LSMS · Recrutement",
  description:
    "Los Santos Medical Services — rejoignez une equipe medicale structuree, reactive et disponible 24/7 sur Los Santos.",
};

/**
 * Groupe de routes LSMS : isole le site du theme global et fournit les polices
 * du theme LSMS. Chaque page embarque son propre header Liquid Glass.
 */
export default function LsmsLayout({
  children,
}: Readonly<{ children: React.ReactNode }>) {
  return (
    <div
      className={`${inter.variable} ${saira.variable} ${barlow.variable} ${specialElite.variable} ${caveat.variable}`}
      style={{
        fontFamily: "var(--font-inter), system-ui, sans-serif",
        background: "#04080a",
        minHeight: "100vh",
      }}
    >
      {children}
    </div>
  );
}

/* Theme LSMS — Liquid Glass sombre medical (teal / rouge sang) */

/* Le body global est teinte : le theme LSMS le repeint des qu'une de ses
   surfaces est presente (header/footer/pages). */
body:has(.lsms-glass),
body:has(.lsms-root) {
  background: #04080a;
}

:root {
  --lsms-teal: #14b8a6;
  --lsms-teal-light: #5eead4;
  --lsms-red: #e23b4e;
  --lsms-red-light: #ff7a8a;
  --lsms-text: #f2f7f6;
  --ease-out: cubic-bezier(0.23, 1, 0.32, 1);
  --ease-swap: cubic-bezier(0.4, 0, 0.2, 1);
  --ease-drawer: cubic-bezier(0.32, 0.72, 0, 1);
}

.lsms-root {
  --lsms-bg: #04080a;
  background: var(--lsms-bg);
  color: var(--lsms-text);
  min-height: 100vh;
  overflow-x: clip;
  position: relative;
}

/* Focus clavier visible : teal sur fond sombre */
.lsms-root a:focus-visible,
.lsms-root button:focus-visible,
.lsms-root summary:focus-visible,
.lsms-root input:focus-visible,
.lsms-root select:focus-visible,
.lsms-root textarea:focus-visible,
.lsms-glass a:focus-visible,
.lsms-glass button:focus-visible {
  outline: 2px solid var(--lsms-teal-light);
  outline-offset: 3px;
  border-radius: 4px;
}

/* ---------- Verre ---------- */
.lsms-glass {
  background: linear-gradient(
    135deg,
    rgba(255, 255, 255, 0.1) 0%,
    rgba(255, 255, 255, 0.04) 40%,
    rgba(255, 255, 255, 0.02) 100%
  );
  -webkit-backdrop-filter: blur(28px) saturate(180%);
  backdrop-filter: blur(28px) saturate(180%);
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-top-color: rgba(255, 255, 255, 0.22);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.18),
    inset 0 -1px 0 rgba(255, 255, 255, 0.05),
    0 24px 60px rgba(0, 0, 0, 0.45);
}

.lsms-pill {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 12px 26px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.08);
  -webkit-backdrop-filter: blur(20px) saturate(170%);
  backdrop-filter: blur(20px) saturate(170%);
  border: 1px solid rgba(255, 255, 255, 0.16);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.2);
  transition:
    background 0.3s var(--ease-out),
    border-color 0.3s var(--ease-out),
    transform 0.3s var(--ease-out);
}

.lsms-cta {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 17px 38px;
  border-radius: 999px;
  font-weight: 600;
  color: #fff;
  background: linear-gradient(180deg, rgba(20, 184, 166, 0.9), rgba(13, 128, 115, 0.9));
  border: 1px solid rgba(255, 255, 255, 0.3);
  --shadow-rgb: 16, 150, 135;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.4),
    0 14px 40px rgba(var(--shadow-rgb), 0.35);
  transition:
    transform 0.3s var(--ease-out),
    box-shadow 0.3s var(--ease-out);
}

/* Lift uniquement sur pointeur precis */
@media (hover: hover) and (pointer: fine) {
  a.lsms-pill:hover {
    background: rgba(255, 255, 255, 0.15);
    border-color: rgba(255, 255, 255, 0.32);
    transform: translateY(-2px);
  }
  a.lsms-cta:hover {
    transform: translateY(-3px) scale(1.02);
    box-shadow:
      inset 0 1px 0 rgba(255, 255, 255, 0.5),
      0 20px 55px rgba(var(--shadow-rgb), 0.5);
  }
  .lsms-card:hover {
    transform: translateY(-8px) scale(1.02);
    border-color: rgba(255, 255, 255, 0.35);
  }
}

/* Feedback d'appui universel */
.lsms-cta:active,
.lsms-pill:active,
.lsms-card:active {
  transform: scale(0.97);
  transition: transform 160ms ease-out;
}

/* ---------- Reveal au scroll (GPU only) ---------- */
.lsms-reveal {
  opacity: 0;
  transform: translateY(26px);
  will-change: opacity, transform;
  transition:
    opacity 0.9s var(--ease-out),
    transform 0.9s var(--ease-out);
  transition-delay: var(--reveal-delay, 0ms);
}
.lsms-reveal.is-visible {
  opacity: 1;
  transform: translateY(0);
}

/* ---------- Keyframes ---------- */
@keyframes lsms-floatY {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-10px); }
}
@keyframes lsms-slowSpin {
  to { transform: rotate(360deg); }
}
@keyframes lsms-pulseRed {
  0%, 49% { opacity: 0.14; }
  50%, 100% { opacity: 0; }
}
@keyframes lsms-pulseTeal {
  0%, 49% { opacity: 0; }
  50%, 100% { opacity: 0.14; }
}

.lsms-float {
  animation: lsms-floatY 8s ease-in-out infinite;
}
.lsms-spin {
  animation: lsms-slowSpin 30s linear infinite;
}
.lsms-spin-slow {
  animation: lsms-slowSpin 64s linear infinite;
}

/* Double pulsation (monitor cardiaque attenué, fond) */
.lsms-pulse-red {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 3;
  animation: lsms-pulseRed 2.2s linear infinite;
  mix-blend-mode: screen;
  background:
    radial-gradient(700px 1000px at 8% 35%, rgba(226, 59, 78, 0.2), transparent 60%),
    radial-gradient(550px 800px at 92% 85%, rgba(226, 59, 78, 0.1), transparent 60%);
}
.lsms-pulse-teal {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 3;
  animation: lsms-pulseTeal 2.2s linear infinite;
  mix-blend-mode: screen;
  background:
    radial-gradient(700px 1000px at 92% 35%, rgba(20, 184, 166, 0.2), transparent 60%),
    radial-gradient(550px 800px at 8% 85%, rgba(94, 234, 212, 0.1), transparent 60%);
}

/* ---------- Intro cinematique : keyframes ---------- */
@keyframes lsms-intro-haloPulse { 0%, 100% { transform: scale(1); opacity: 0.55; } 50% { transform: scale(1.09); opacity: 0.95; } }
@keyframes lsms-intro-ringOut { 0% { transform: scale(0.82); opacity: 0.9; } 100% { transform: scale(1.5); opacity: 0; } }
@keyframes lsms-intro-hintUp { from { opacity: 0; transform: translateY(14px); } to { opacity: 1; transform: none; } }
@keyframes lsms-intro-caretBlink { 0%, 100% { opacity: 1; } 50% { opacity: 0.15; } }
@keyframes lsms-intro-slowSpin { to { transform: rotate(360deg); } }

/* ---------- Accessibilite ---------- */
@media (prefers-reduced-motion: reduce) {
  .lsms-root *,
  .lsms-root *::before,
  .lsms-root *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
  .lsms-reveal {
    opacity: 1;
    transform: none;
  }
}

"use client";

import { useEffect, useRef } from "react";

/**
 * Reveal au scroll : stagger par batch intersecte (cap 3 x 70 ms).
 * GPU-only (transform/opacity).
 */
export function Reveal({
  children,
  className = "",
  ...rest
}: React.HTMLAttributes<HTMLDivElement>) {
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const io = new IntersectionObserver(
      (entries) => {
        let batchIdx = 0;
        entries.forEach((e) => {
          if (!e.isIntersecting) return;
          const target = e.target as HTMLElement;
          io.unobserve(target);
          const delay = Math.min(batchIdx++, 3) * 70;
          target.style.setProperty("--reveal-delay", `${delay}ms`);
          target.classList.add("is-visible");
        });
      },
      { threshold: 0.12, rootMargin: "0px 0px -40px 0px" }
    );
    io.observe(el);
    return () => io.disconnect();
  }, []);

  return (
    <div ref={ref} className={`lsms-reveal ${className}`} {...rest}>
      <div className={className.includes("h-full") ? "flex h-full w-full flex-col" : "w-full"}>{children}</div>
    </div>
  );
}

