                          </span>
                          {f.note && <span className="mb-3 block text-[13px] leading-[1.6] text-[#54706A]">{f.note}</span>}
                          {f.type === "textarea" ? (
                            <textarea
                              rows={f.rows ?? 3}
                              value={values[f.key] ?? ""}
