                  >
                    {sending ? "Transmission…" : "Deposer le dossier"}
                  </button>
                </div>
                <p className="mt-3.5 text-center text-[13px] text-[#54706A]">Votre dossier sera transmis a la direction des ressources humaines du LSMS.</p>
              </form>
            ) : (
