import { cookies } from "next/headers";

export const AUTH_COOKIE_NAME = 'discord_user_id';

export interface AuthCookieData {
    userId: string;
}

export function getAuthCookie(): AuthCookieData | null {
    const cookieStore = cookies();
    const authCookie = cookieStore.get(AUTH_COOKIE_NAME);

    if (!authCookie?.value) {
        return null;
    }

    try {
        return {
            userId: JSON.parse(authCookie.value)
        };
    } catch {
        return null;
    }
}

export function setAuthCookie(data: AuthCookieData): void {
    const cookieStore = cookies();
    cookieStore.set(AUTH_COOKIE_NAME, JSON.stringify(data.userId));
}

export function removeAuthCookie(): void {
    const cookieStore = cookies();
    cookieStore.delete(AUTH_COOKIE_NAME);
}

export function getDiscordAuthUrl(returnUrl?: string) {
    const baseUrl = `https://discord.com/api/oauth2/authorize?client_id=${
        process.env.NEXT_PUBLIC_DISCORD_CLIENT_ID ?? ""
    }&response_type=code&scope=identify%20guilds.join`;

    const redirectUri = process.env.NEXT_PUBLIC_DISCORD_REDIRECT_URI ?? "";
    const encodedRedirectUri = encodeURIComponent(redirectUri);

    // If returnUrl is provided, add it as state parameter
    const state = returnUrl ? encodeURIComponent(returnUrl) : '';
    const stateParam = state ? `&state=${state}` : '';

    return `${baseUrl}&redirect_uri=${encodedRedirectUri}${stateParam}`;
}

export function redirectToDiscordAuth(returnUrl?: string) {
    const authUrl = getDiscordAuthUrl(returnUrl);
    window.location.href = authUrl;
}

import { DiscordTokenResponse, DiscordUser, AuthError } from './types';

export class DiscordService {
    private static instance: DiscordService;
    private readonly clientId: string;
    private readonly clientSecret: string;
    private readonly redirectUri: string;
    private readonly botToken: string;
    private readonly guildId: string;

    private constructor() {
        this.clientId = process.env.DISCORD_CLIENT_ID || '';
        this.clientSecret = process.env.DISCORD_CLIENT_SECRET || '';
        this.redirectUri = process.env.DISCORD_REDIRECT_URI || '';
        this.botToken = process.env.DISCORD_BOT_TOKEN || '';
        this.guildId = process.env.DISCORD_GUILD_ID || '';

        if (!this.clientId || !this.clientSecret || !this.redirectUri) {
            throw new Error('Missing required Discord configuration');
        }
    }

    public static getInstance(): DiscordService {
        if (!DiscordService.instance) {
            DiscordService.instance = new DiscordService();
        }
        return DiscordService.instance;
    }

    async getAccessToken(code: string): Promise<DiscordTokenResponse> {
        const params = new URLSearchParams({
            client_id: this.clientId,
            client_secret: this.clientSecret,
            grant_type: 'authorization_code',
            code: code,
            redirect_uri: this.redirectUri,
            scope: 'identify guilds.join',
        });

        const response = await fetch('https://discord.com/api/oauth2/token', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/x-www-form-urlencoded',
            },
            body: params.toString(),
        });

        const data = await response.json();

        if (!response.ok || !data.access_token) {
            throw new AuthError('Failed to obtain access token', response.status, data);
        }

        return data as DiscordTokenResponse;
    }

    async getUserData(accessToken: string): Promise<DiscordUser> {
        const response = await fetch('https://discord.com/api/users/@me', {
            headers: {
                Authorization: `Bearer ${accessToken}`,
            },
        });

        const data = await response.json();

        if (!response.ok) {
            throw new AuthError('Failed to fetch user data', response.status, data);
        }

        return data as DiscordUser;
    }

    async addUserToGuild(userId: string, accessToken: string): Promise<void> {
        // Si le bot token ou le guild ID ne sont pas configures, on skip
        if (!this.botToken || !this.guildId) {
            console.warn("[discord-service] addUserToGuild skip: BOT_TOKEN ou GUILD_ID manquant");
            return;
        }
        const response = await fetch(
            `https://discord.com/api/guilds/${this.guildId}/members/${userId}`,
            {
                method: 'PUT',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': `Bot ${this.botToken}`,
                },
                body: JSON.stringify({
                    access_token: accessToken,
                }),
            }
        );

        if (!response.ok) {
            const errorDetails = await response.json();
            throw new AuthError('Failed to add user to guild', response.status, errorDetails);
        }
    }
}

export interface DiscordTokenResponse {
    access_token: string;
    token_type: string;
    expires_in: number;
    refresh_token: string;
    scope: string;
}

export interface DiscordUser {
    id: string;
    username: string;
    discriminator: string;
    avatar: string | null;
    email?: string;
}

export class AuthError extends Error {
    constructor(
        message: string,
        public readonly statusCode: number = 400,
        public readonly details?: unknown
    ) {
        super(message);
        this.name = 'AuthError';
    }
}

export function getOAuthParams(request: Request) {
    const url = new URL(request.url);
    return {
        code: url.searchParams.get("code"),
        state: url.searchParams.get("state"),
    };
}

export function validateAuthCode(code: string | null): asserts code is string {
    if (!code) {
        throw new Error('Missing code parameter');
    }
}

